func TestStructuredHelpJSONFlag(t *testing.T) {
	out, errOut, err := executeRootForHelpTest("pages", "update", "--help", "--json")
	if err != nil {
		t.Fatalf("Execute() error = %v; stderr=%q", err, errOut)
	}

	help := decodeStructuredHelp(t, out)
	if help.Type != "help" {
		t.Fatalf("type = %q, want help", help.Type)
	}
	if help.Command != "notion-pp-cli pages update" {
		t.Fatalf("command = %q, want notion-pp-cli pages update", help.Command)
	}
	if help.Use != "update <page_id>" {
		t.Fatalf("use = %q, want update <page_id>", help.Use)
	}
	if !help.JSON {
		t.Fatalf("json = false, want true")
	}
	if help.Agent {
		t.Fatalf("agent = true, want false for explicit --json help")
	}
	if !hasHelpFlag(help.Flags.Local, "cover") {
		t.Fatalf("local flags should include pages update --cover: %+v", help.Flags.Local)
	}
	if !hasHelpFlag(help.Flags.Inherited, "json") {
		t.Fatalf("inherited flags should include root --json: %+v", help.Flags.Inherited)
	}
	if strings.Contains(out, "Usage:") {
		t.Fatalf("JSON help should not contain Cobra human usage text: %q", out)
	}
}

